// Mahnlauf, Kernlogik: Unterworkflow "Zahlstand lesen", Quelle Sheet (BAUPLAN d, e, g; Baustein 5).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Das Zusammenspiel aus Buch
// (zahlungseingaenge.js), Parsern, Zuordnung (zuordnung.js) und Frische (stufen.js). Die Funktionen
// der anderen Module kommen als Parameter k herein - im Code-Node stehen sie im selben Rumpf, in den
// Tests kommen sie per require.
//
// Regel (BAUPLAN h): Erwartbares kommt als Status bzw. Meldung zurueck (unlesbare CSV, Datei im
// anderen Format, keine Datei, Ordner fehlt). Geworfen wird nur bei Unerwartetem.
// Belastungen (Lastschriften, Abbuchungen) sind keine Meldung an den Betrieb, sie gehen still ins Protokoll
// (Entscheidung Elias 25.09.2026, Baustein 10 Teil A 2); Klaerfall bleiben Storno und Ruecklastschrift.

var ZS_STILL = ['Belastungen nicht gezählt'];

function zsText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function zsIstDatum(s) {
  var r = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s));
  if (!r) return false;
  var d = new Date(Date.UTC(+r[1], +r[2] - 1, +r[3]));
  return d.getUTCFullYear() === +r[1] && d.getUTCMonth() === +r[2] - 1 && d.getUTCDate() === +r[3];
}

// Eingang { quelle, stichtag, posten, schreiben }. posten: Items von "Offene Posten lesen" (art
// posten). schreiben: true schreibt das Buch fort, false (Modus trocken) rechnet nur.
function pruefeEingangZahlstand(e) {
  if (!e || typeof e !== 'object') throw new Error('Zahlstand lesen - Eingang fehlt');
  var q = e.quelle;
  if (!q || typeof q !== 'object' || !zsText(q.art)) throw new Error('Zahlstand lesen - Eingang ohne quelle.art');
  if (!zsIstDatum(e.stichtag)) throw new Error('Zahlstand lesen - Stichtag nicht im Format JJJJ-MM-TT');
  if (!Array.isArray(e.posten)) throw new Error('Zahlstand lesen - Eingang ohne posten');
  if (typeof e.schreiben !== 'boolean') throw new Error('Zahlstand lesen - Eingang ohne schreiben (true oder false)');
  if (q.art !== 'Sheet') {
    return { weiter: false, status: 'quelle_nicht_gebaut', quelle: q, stichtag: e.stichtag, schreiben: e.schreiben,
      meldung: 'Quelle "' + zsText(q.art) + '" ist vorbereitet, nicht gebaut' };
  }
  if (!zsText(q.tabelle_id)) throw new Error('Zahlstand lesen - Eingang ohne quelle.tabelle_id');
  return { weiter: true, status: '', quelle: q, stichtag: e.stichtag, schreiben: e.schreiben, tabelle_id: zsText(q.tabelle_id),
    posten: e.posten };
}

// Antwort von Drive files.list -> Dateien { id, name, mimeType }, nach Namen sortiert. Ordner und
// Google-eigene Dokumente sind keine Kontoauszuege.
function dateienAusDrive(body) {
  return ((body && body.files) || [])
    .filter(function (f) { return String(f.mimeType || '').indexOf('application/vnd.google-apps.') !== 0; })
    .map(function (f) { return { id: f.id, name: f.name, mimeType: f.mimeType || '' }; })
    .sort(function (a, b) { return a.name < b.name ? -1 : a.name > b.name ? 1 : 0; });
}

// p = { einstellungen (Kernform), bestand (Zeilen aus leseZahlungseingaenge), dateien: [{ datei,
//       format, ergebnis }], gemeldet: [{ datei, grund }], posten, stichtag }
// k = { ordneZahlungenZu, pruefeFrische, schreibeFort, zuordnungsEingabe, schreibauftrag }
// -> { status: {...}, zahlstand: [je Posten], auftrag: { berechnet, neu } }
function berechneZahlstand(p, k) {
  var e = p.einstellungen || {};
  var meldungen = [];
  var protokoll = [];
  var stand = null;
  var gelesen = [];
  (p.dateien || []).forEach(function (d) {
    var r = d.ergebnis || {};
    if (!r.ok) {
      var f = r.fehler || {};
      meldungen.push({ art: 'Kontoauszug unlesbar', datei: d.datei, zeile: f.zeile, text: f.grund });
      return;
    }
    gelesen.push(d);
    if (r.stand && (stand === null || r.stand > stand)) stand = r.stand;
    (r.hinweise || []).forEach(function (h) {
      if (ZS_STILL.indexOf(h.art) >= 0) protokoll.push({ aktion: h.art, grund: 'Datei ' + d.datei + ' · ' + h.anzahl });
      else meldungen.push({ art: h.art, datei: d.datei, text: String(h.anzahl) });
    });
  });
  (p.gemeldet || []).forEach(function (g) { meldungen.push({ art: 'Datei nicht gelesen', datei: g.datei, text: g.grund }); });
  var frische = k.pruefeFrische(stand, p.stichtag, e.max_alter_auszug);
  var fort = k.schreibeFort(p.bestand || [], gelesen);
  var alle = (p.bestand || []).concat(fort.neu);
  var ein = k.zuordnungsEingabe(alle);
  var rechnungen = (p.posten || []).map(function (x) {
    return { rechnungsnr: x.rechnungsnr, kunde: x.kunde, betrag_brutto_cent: x.betrag_brutto_cent, mahnsperre: x.mahnsperre };
  });
  var zuo = k.ordneZahlungenZu({ rechnungen: rechnungen, zahlungen: ein.zahlungen, klaerfaelle: ein.klaerfaelle,
    manuell: ein.manuell, muster: e.muster });
  zuo.meldungen.forEach(function (m) { meldungen.push(m); });
  var auftrag = k.schreibauftrag((p.bestand || []).length, alle, zuo);
  return {
    status: {
      status: 'ok',
      auszug_stand: stand,
      auszug_frisch: frische.frisch,
      frische_grund: frische.grund,
      auszugsformat: zsText(e.auszugsformat),
      dateien: (p.dateien || []).map(function (d) {
        var r = d.ergebnis || {};
        return { datei: d.datei, format: d.format, ok: !!r.ok, stand: r.ok ? r.stand : null };
      }),
      neu: fort.neu.length,
      schon_im_buch: fort.schon_im_buch,
      buch_zeilen: alle.length,
      meldungen: meldungen,
      protokoll: protokoll,
    },
    zahlstand: zuo.rechnungen.map(function (r) {
      return {
        rechnungsnr: r.rechnungsnr, bezahlt_cent: r.bezahlt_cent, rest_cent: r.rest_cent, status: r.status,
        ueberschuss_cent: r.ueberschuss_cent, klaerfall_halt: r.klaerfall_halt, klaerfall_schluessel: r.klaerfall_schluessel,
        dublette: r.dublette, stand_datum: stand, stand_quelle: 'Zahlungseingänge',
      };
    }),
    auftrag: auftrag,
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { pruefeEingangZahlstand, dateienAusDrive, berechneZahlstand };
}

// ==== Treiber, nicht Teil des Kerns (bau/werkzeuge/zz_bau_b34.py) ====
const e = pruefeEingangZahlstand($input.first().json);
if (e.weiter) e.url_tabelle = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(e.tabelle_id) + '/values:batchGet?ranges=' + encodeURIComponent("'Einstellungen'") + '&ranges=' + encodeURIComponent("'Zahlungseingänge'") + '&valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
return [{ json: e }];

const e = $input.first().json;
return [{ json: { art: 'status', status: e.status, auszug_stand: null, auszug_frisch: false,
  meldungen: [{ art: 'Quelle', text: e.meldung }], geschrieben: false } }];

// Mahnlauf, Kernlogik: Blatt "Einstellungen" lesen (BAUPLAN b, Baustein 5/6).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Eingabe wie von values.get mit
// UNFORMATTED_VALUE/SERIAL_NUMBER: Spalte A Schluessel, Spalte B Wert. Ausgabe ist die Form,
// die planeLauf, die Parser und waehleAuszugsdateien erwarten. Die Adressen (Testempfaenger,
// Absenderadresse, Antwort an, Meldeadresse) kommen NIE in die Ausgabe - nur "gesetzt ja/nein";
// wer sie zum Senden braucht, liest sie am Versandschritt selbst (Baustein 7).
// Unlesbare Zahlen werden NaN; planeLauf wirft dann "Einstellung ungueltig" (fail-closed).

var EI_FELDER = [
  ['Modus', 'modus', 'klein'],
  ['Testempfänger', 'testempfaenger', 'adresse'],
  ['Stichtag (nur Test)', 'stichtag_test', 'datum'],
  ['Absendername', 'absendername', 'text'],
  ['Absenderadresse', 'absenderadresse', 'adresse'],
  ['Antwort an', 'antwort_an', 'adresse'],
  ['Firmenname', 'firma', 'text'],
  ['IBAN', 'iban', 'text'],
  ['BIC', 'bic', 'text'],
  ['Signatur', 'signatur', 'text'],
  ['Meldeadresse Betrieb', 'meldeadresse', 'adresse'],
  ['Intervall Erinnerung', 'intervall_erinnerung', 'zahl'],
  ['Intervall 1. Mahnung', 'intervall_mahnung1', 'zahl'],
  ['Intervall letzte Mahnung', 'intervall_letzte_mahnung', 'zahl'],
  ['Intervall Übergabe', 'intervall_uebergabe', 'zahl'],
  ['Zahlungsfrist in der Mahnung', 'zahlungsfrist', 'zahl'],
  ['Freigabemodus Erinnerung', 'freigabemodus_erinnerung', 'text'],
  ['Freigabemodus 1. Mahnung', 'freigabemodus_mahnung1', 'text'],
  ['Freigabemodus letzte Mahnung', 'freigabemodus_letzte_mahnung', 'text'],
  ['Freigabemodus Übergabe', 'freigabemodus_uebergabe', 'text'],
  ['Max. Alter Kontoauszug', 'max_alter_auszug', 'zahl'],
  ['Kontoauszug-Ordner', 'kontoauszug_ordner', 'text'],
  ['Auszugsformat', 'auszugsformat', 'text'],
  ['CSV: Trennzeichen', 'csv.trennzeichen', 'roh'],
  ['CSV: Zeichensatz', 'csv.zeichensatz', 'text'],
  ['CSV: Dezimalzeichen', 'csv.dezimalzeichen', 'text'],
  ['CSV: Datumsformat', 'csv.datumsformat', 'text'],
  ['CSV: Kopfzeile in Zeile', 'csv.kopfzeile', 'zahl'],
  ['CSV: Spalte Buchungsdatum', 'csv.spalte_buchungsdatum', 'text'],
  ['CSV: Spalte Betrag', 'csv.spalte_betrag', 'text'],
  ['CSV: Spalte Soll/Haben', 'csv.spalte_soll_haben', 'text'],
  ['CSV: Spalte Verwendungszweck', 'csv.spalte_verwendungszweck', 'text'],
  ['CSV: Spalte Auftraggeber', 'csv.spalte_auftraggeber', 'text'],
  ['CSV: Spalte IBAN', 'csv.spalte_iban', 'text'],
  ['CSV: Spalte Referenz', 'csv.spalte_referenz', 'text'],
  ['Rechnungsnummer-Muster', 'muster', 'text'],
  ['Mindestbetrag', 'mindestbetrag_cent', 'cent'],
  ['Höchstzahl Mails je Lauf', 'hoechstzahl_mails', 'zahl'],
  ['Versandtage', 'versandtage', 'text'],
  ['Uhrzeit', 'uhrzeit', 'text'],
  ['PDF anhängen', 'pdf_anhaengen', 'klein'],
  ['Quelle', 'quelle', 'text'],
];

function eiText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function eiZahl(v) {
  if (typeof v === 'number') return v;
  var s = eiText(v);
  return /^-?\d+$/.test(s) ? Number(s) : NaN;
}

// 5 -> 500; "5,00" -> 500; "1.234,5" -> 123450. Sonst NaN.
function eiCent(v) {
  if (typeof v === 'number' && isFinite(v)) return Math.round(v * 100);
  var s = eiText(v).replace(/\s*€$/, '');
  if (!/^\d{1,3}(\.\d{3})*(,\d{1,2})?$|^\d+(,\d{1,2})?$/.test(s)) return NaN;
  var t = s.replace(/\./g, '').split(',');
  return parseInt(t[0], 10) * 100 + parseInt(((t[1] || '') + '00').slice(0, 2), 10);
}

function eiDatum(v) {
  if (typeof v === 'number' && isFinite(v) && v >= 1) {
    var d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 86400000);
    var z = function (n) { return (n < 10 ? '0' : '') + n; };
    return d.getUTCFullYear() + '-' + z(d.getUTCMonth() + 1) + '-' + z(d.getUTCDate());
  }
  var s = eiText(v);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : (s === '' ? '' : 'ungültig: ' + s);
}

// werte: [[Schluessel, Wert, Bemerkung], ...] (Kopfzeile darf dabei sein).
// -> { ok, fehlend: [Schluessel], kern: {...}, adressen_gesetzt: {...} }
function leseEinstellungen(werte) {
  var roh = {};
  (werte || []).forEach(function (z) {
    var k = eiText(z && z[0]);
    if (k && !Object.prototype.hasOwnProperty.call(roh, k)) roh[k] = z.length > 1 ? z[1] : '';
  });
  var aus = { ok: true, fehlend: [], kern: { csv: {} }, adressen_gesetzt: {} };
  EI_FELDER.forEach(function (f) {
    if (!Object.prototype.hasOwnProperty.call(roh, f[0])) { aus.fehlend.push(f[0]); return; }
    var v = roh[f[0]];
    if (f[2] === 'adresse') { aus.adressen_gesetzt[f[1]] = eiText(v) !== ''; return; }
    var w;
    if (f[2] === 'zahl') w = eiZahl(v);
    else if (f[2] === 'cent') w = eiCent(v);
    else if (f[2] === 'datum') w = eiDatum(v);
    else if (f[2] === 'klein') w = eiText(v).toLowerCase();
    else if (f[2] === 'roh') w = v === undefined || v === null ? '' : String(v);
    else w = eiText(v);
    if (f[1].indexOf('csv.') === 0) aus.kern.csv[f[1].slice(4)] = w;
    else aus.kern[f[1]] = w;
  });
  aus.ok = aus.fehlend.length === 0;
  return aus;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { leseEinstellungen };
}

// Mahnlauf, Kernlogik: Blatt "Zahlungseingänge" als Buch (BAUPLAN b und d, Baustein 5).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Das Blatt ist das Buch aller
// Buchungen, die je gelesen wurden: neue Schluessel werden angehaengt, nie geaendert; die
// Zuordnung wird bei jedem Lauf aus dem GANZEN Buch neu gerechnet (nie hochgezaehlt) und nur in
// die berechneten Spalten zurueckgeschrieben. Die Spalte "manuelle Zuordnung" schreibt nur der
// Betrieb. Werte wie die Sheets-API sie mit UNFORMATTED_VALUE/SERIAL_NUMBER liefert.
//
// Doppelzaehlung verhindern (Auftrag 25.09.2026, Teil A 3): Steht die Bankreferenz einer neuen
// Buchung schon im Buch - unter einem ANDEREN Schluessel -, wird sie Klaerfall "Referenz bereits
// vorhanden" und nicht verbucht. Derselbe Schluessel ist dieselbe Buchung (Auszug zweimal
// gelesen) und wird nicht noch einmal angehaengt.

var ZE_SPALTEN = [
  'Buchungsschlüssel', 'Bankreferenz', 'Buchungsdatum', 'Betrag', 'Währung', 'Auftraggeber', 'IBAN',
  'Verwendungszweck', 'Strukturierte Referenz', 'Quelldatei', 'Klärfall aus Auszug',
  'zugeordnete Rechnungsnr.', 'Zuordnung', 'Kandidaten', 'Grund', 'manuelle Zuordnung',
];

var ZE_TAG0 = Date.UTC(1899, 11, 30);

function zeText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function zeZwei(n) {
  return (n < 10 ? '0' : '') + n;
}

function zeSerialZuDatum(v) {
  if (typeof v !== 'number' || !isFinite(v) || v < 1) return '';
  var d = new Date(ZE_TAG0 + Math.floor(v) * 86400000);
  return d.getUTCFullYear() + '-' + zeZwei(d.getUTCMonth() + 1) + '-' + zeZwei(d.getUTCDate());
}

function zeDatumZuSerial(d) {
  var r = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(d));
  if (!r) return '';
  return (Date.UTC(+r[1], +r[2] - 1, +r[3]) - ZE_TAG0) / 86400000;
}

function zeSpalte(i) {
  return i < 26 ? String.fromCharCode(65 + i) : String.fromCharCode(64 + Math.floor(i / 26)) + String.fromCharCode(65 + (i % 26));
}

// werte: [[Kopfzeile], [Zeile], ...] -> { ok, fehlend_spalten, doppelte_spalten, reihenfolge_falsch,
// abweichend, zusaetzlich, zeilen, hinweise, naechste_zeile }. Die Kopfzeile muss EXAKT ZE_SPALTEN
// sein - Namen ungetrimmt, Reihenfolge, keine weitere nichtleere Spalte (Auftrag 25.09.2026, Teil A 1):
// zurueckgeschrieben wird nach Spaltenbuchstaben (schreibBereiche), eine verschobene Spalte bekaeme
// sonst fremde Werte. Bei Abweichung keine Zeilen - wer ok false bekommt, schreibt nicht.
function leseZahlungseingaenge(werte) {
  var w = werte || [];
  var roh = (w[0] || []).map(function (v) { return v === undefined || v === null ? '' : String(v); });
  var kopf = roh.map(zeText);
  var fehlend = ZE_SPALTEN.filter(function (s) { return kopf.indexOf(s) < 0; });
  var doppelt = ZE_SPALTEN.filter(function (s) {
    var i = kopf.indexOf(s);
    return i >= 0 && kopf.indexOf(s, i + 1) >= 0;
  });
  var reihenfolge = !fehlend.length && ZE_SPALTEN.some(function (s, i) { return kopf[i] !== s; });
  var abweichend = [];
  ZE_SPALTEN.forEach(function (s, i) {
    if (roh[i] !== s) abweichend.push(zeSpalte(i) + ': erwartet „' + s + '“, steht „' + (roh[i] === undefined ? '' : roh[i]) + '“');
  });
  var zusaetzlich = [];
  for (var j = ZE_SPALTEN.length; j < roh.length; j++) if (roh[j] !== '') zusaetzlich.push(zeSpalte(j) + ': ' + roh[j]);
  var aus = { ok: !fehlend.length && !doppelt.length && !reihenfolge,
    fehlend_spalten: fehlend, doppelte_spalten: doppelt, reihenfolge_falsch: reihenfolge, abweichend: abweichend,
    zusaetzlich: zusaetzlich, zeilen: [], hinweise: [], naechste_zeile: Math.max(w.length, 1) + 1 };
  if (abweichend.length || zusaetzlich.length) aus.ok = false; // Sicherung Kopfzeile exakt
  if (!aus.ok) return aus;
  var idx = {};
  ZE_SPALTEN.forEach(function (s) { idx[s] = kopf.indexOf(s); });
  for (var r = 1; r < w.length; r++) {
    var reihe = w[r] || [];
    if (reihe.every(function (v) { return zeText(v) === ''; })) continue;
    var feld = function (s) { return reihe[idx[s]]; };
    var nr = r + 1;
    var sl = zeText(feld('Buchungsschlüssel'));
    if (!sl) {
      sl = 'ZEILE-' + nr;
      aus.hinweise.push({ zeile: nr, text: 'Zeile ohne Buchungsschlüssel' });
    }
    var betrag = feld('Betrag');
    var cent = typeof betrag === 'number' && isFinite(betrag) ? Math.round(betrag * 100) : null;
    if (cent === null) aus.hinweise.push({ zeile: nr, text: 'Betrag ist keine Zahl' });
    aus.zeilen.push({
      zeile: nr,
      schluessel: sl,
      bankreferenz: zeText(feld('Bankreferenz')),
      buchungsdatum: zeSerialZuDatum(feld('Buchungsdatum')),
      betrag_cent: cent,
      waehrung: zeText(feld('Währung')) || 'EUR',
      auftraggeber: zeText(feld('Auftraggeber')),
      iban: zeText(feld('IBAN')),
      verwendungszweck: zeText(feld('Verwendungszweck')),
      referenz: zeText(feld('Strukturierte Referenz')),
      quelle: zeText(feld('Quelldatei')),
      klaerfall: zeText(feld('Klärfall aus Auszug')),
      manuell: zeText(feld('manuelle Zuordnung')),
    });
  }
  return aus;
}

// Zahlung oder Klaerfall eines Parsers -> Buchzeile. CSV: referenz ist die Bankreferenz.
// CAMT: bankreferenz ist AcctSvcrRef, referenz die strukturierte Referenz (CdtrRefInf).
function zeAusZahlung(z, datei, klaerfall) {
  var camt = Object.prototype.hasOwnProperty.call(z, 'bankreferenz');
  return {
    zeile: 0,
    schluessel: z.schluessel,
    bankreferenz: zeText(camt ? z.bankreferenz : z.referenz),
    buchungsdatum: z.buchungsdatum,
    betrag_cent: z.betrag_cent,
    waehrung: zeText(z.waehrung) || 'EUR',
    auftraggeber: zeText(z.auftraggeber),
    iban: zeText(z.iban),
    verwendungszweck: zeText(z.verwendungszweck),
    referenz: camt ? zeText(z.referenz) : '',
    quelle: zeText(z.quelle) || zeText(datei),
    klaerfall: zeText(klaerfall),
    manuell: '',
  };
}

// bestand: Zeilen aus leseZahlungseingaenge. dateien: [{ datei, ergebnis }] in Lesereihenfolge,
// ergebnis wie von parseKontoauszugCsv/-Camt. -> { neu: [Buchzeilen], schon_im_buch }
function schreibeFort(bestand, dateien) {
  var imBuch = {};
  var refs = {};
  (bestand || []).forEach(function (z) {
    imBuch[z.schluessel] = true;
    if (z.bankreferenz && refs[z.bankreferenz] === undefined) refs[z.bankreferenz] = z.schluessel;
  });
  var neu = [];
  var schon = 0;
  (dateien || []).forEach(function (d) {
    var e = d && d.ergebnis;
    if (!e || !e.ok) return;
    var liste = (e.zahlungen || []).map(function (z) { return [z, '']; })
      .concat((e.klaerfaelle || []).map(function (k) { return [k, zeText(k.grund) || 'Klärfall aus dem Auszug']; }));
    // Innerhalb einer Datei entscheidet der Parser (Teile einer Sammelbuchung teilen die Referenz,
    // doppelte Referenzen sind dort schon Klaerfall). Gegen das Buch und gegen frueher gelesene
    // Dateien gilt die Regel; die Referenzen dieser Datei zaehlen erst fuer die naechste.
    var dieseDatei = {};
    liste.forEach(function (p) {
      var z = p[0];
      if (imBuch[z.schluessel]) { schon++; return; }
      var zeile = zeAusZahlung(z, d.datei, p[1]);
      var vorhanden = zeile.bankreferenz ? refs[zeile.bankreferenz] : undefined;
      if (vorhanden !== undefined && vorhanden !== zeile.schluessel && !zeile.klaerfall) zeile.klaerfall = 'Referenz bereits vorhanden'; // Sicherung Referenz bereits vorhanden
      imBuch[zeile.schluessel] = true;
      if (zeile.bankreferenz && dieseDatei[zeile.bankreferenz] === undefined) dieseDatei[zeile.bankreferenz] = zeile.schluessel;
